  {
    "id": "word/document.xml:p0341",
    "index": 341,
    "text": "第4節　自らの遺体を焼くよう遺言した人",
    "style": "Heading2",
    "links": []
  },
  {
    "id": "word/document.xml:p0342",
    "index": 342,
    "text": "ムスリム2756。",
