    {
      "id": "p04",
      "kind": "quran_heading",
      "text": "言いなさい。「アッラー、唯一の御方。",
      "sentences": [
        {
          "id": "p04.s01",
          "segments": [
            {
              "type": "quran_excerpt",
              "binding": "Q:0",
              "text": "言いなさい。「アッラー、唯一の御方。"
