    {
      "id": "p07",
      "kind": "quran_heading",
      "text": "アッラー、永遠にして絶対の御方。",
      "sentences": [
        {
          "id": "p07.s01",
          "segments": [
            {
              "type": "quran_excerpt",
              "binding": "Q:42",
              "text": "アッラー、永遠にして絶対の御方。"
