  "nonQ_selected17": {
    "N:12": {
      "text": "私たちにはアッラーさえいらっしゃれば十分です。そしてアッラーこそ最高の庇護者です",
      "type": "published_nonq_excerpt",
      "actual_identity": "Bukhari4563, Ibn Abbas; Ibrahim speech",
      "short_credit": "IslamHouse・特別なズィクル（サイード佐藤訳）"
    },
    "N:24": {
      "text": "イフラース章は、クルアーンの三分の一に等しい。",
      "type": "own_nonq_meaning",
      "actual_identity": "Muslim811a, Abu Darda; Prophetic speech",
      "short_credit": "ムスリム伝承集（意味）"
    },
    "N:30": {
      "text": "彼らがアッラーを崇拝し、かれに何ものも並べたりしないことだ",
      "type": "published_nonq_excerpt",
      "actual_identity": "HEC65007; Muadh; Bukhari2856/Muslim30 variant",
      "short_credit": "ハディース百科事典"
    },
    "N:32": {
      "text": "アッラーは唯一だ、アッラーは唯一だ",
      "type": "published_nonq_excerpt",
      "actual_identity": "Tokyo basic knowledge p218 Bilal utterance; Arabic IbnMajah150 independently supports; book is not full published IbnMasud report",
      "short_credit": "イスラームの基本知識（東京ジャーミイ）"
    },
    "N:34": {
      "text": "唯一の御方、唯一の御方",
      "type": "own_nonq_meaning",
      "actual_identity": "Ibn Hisham actual Badr slogan; historical report, not Prophetic order",
      "short_credit": "イブン・ヒシャーム『預言者伝』（意味）"
    },
    "N:36": {
      "text": "唯一で並ぶ者無きアッラー以外に崇拝されるべきものはありません。主権と讃美はかれにこそ属し、かれは全てにおいて全能です。",
      "type": "published_nonq_excerpt",
      "actual_identity": "Hisn93 p86 morning100; exact common formula, source framing Bukhari3293 day100 separately",
      "short_credit": "ムスリムの砦（サイード佐藤・ファーティマ佐藤訳）"
    },
    "N:49": {
      "text": "乳離れした子ラクダが母を切に慕った",
      "type": "own_nonq_meaning",
      "actual_identity": "reported lexical example; uncertain etymology, not scripture",
      "short_credit": "アラビア語の用例（意味）"
    },
    "N:60": {
      "text": "アッラーは、全ての病気のための薬をも創造された",
      "type": "published_nonq_meaning",
      "actual_identity": "Tokyo basic knowledge p180 explicitly published meaning, no narrator/number given; Bukhari5678 independently supports meaning",
      "short_credit": "イスラームの基本知識（東京ジャーミイ）"
    },
    "N:62": {
      "text": "彼を癒して下さい。あなたこそが癒されるお方であり、あなたの癒しの他に癒しはありません。",
      "type": "published_nonq_excerpt",
      "actual_identity": "Bukhari5743/Muslim2191, Aisha; exact Japanese PDF6(print5), note29",
      "short_credit": "病人のお見舞いに関する礼儀作法（サイード佐藤訳）"
    },
    "N:70": {
      "text": "アブー・バクルよ、アッラーが第三の御方として共におられる二人について、どう思うのか。",
      "type": "own_nonq_meaning",
      "actual_identity": "Bukhari3653/Muslim2381 Abu Bakr; Prophetic speech",
      "short_credit": "ブハーリー・ムスリム伝承集（意味）"
