        "paragraph_cp_end": 1245,
        "paragraph_utf16_start": 1221,
        "paragraph_utf16_end": 1245,
        "reference": "113:1",
        "edition": "Tokyo Camii クルアーン 日本語読解 PDF edition01_03 2022-02-01",
