        "paragraph_cp_end": 1273,
        "paragraph_utf16_start": 1250,
        "paragraph_utf16_end": 1273,
        "reference": "114:1",
        "edition": "Tokyo Camii クルアーン 日本語読解 PDF edition01_03 2022-02-01",
        "parent_cp_start": 0,
        "parent_cp_end": 23,
        "parent_utf16_start": 0,
        "parent_utf16_end": 23,
