      {
        "binding": "N:131",
        "type": "own_nonq_meaning",
        "sentence": "p14.s21",
        "paragraph": "p14",
        "text": "杖は打つ者次第、ファーティハ章は読む者次第。",
        "sha256_utf8": "f03b2b375f06b7719608a773c52f9c6ceea84c4880c089a4c3ed6bcaeb7f5cf2",
        "cp_start": 17,
