          "reference": "42:52",
          "edition": "Tokyo Camii クルアーン 日本語読解 PDF edition01_03 2022-02-01",
          "parent_cp_start": 0,
          "parent_cp_end": 31,
          "parent_utf16_start": 0,
          "parent_utf16_end": 31,
          "full_parent_sha256_utf8": "3a8c53034bd9143d8a9b0f3209a7d26cd904a4ce71b99c2f68694ff2ed9766bf"
        }
