          "paragraph_utf16_end": 1311,
          "reference": "12:33",
          "edition": "Tokyo Camii クルアーン 日本語読解 PDF edition01_03 2022-02-01",
          "parent_cp_start": 41,
          "parent_cp_end": 94,
          "parent_utf16_start": 41,
          "parent_utf16_end": 94,
          "full_parent_sha256_utf8": "aaca2d9d4386b499e9b755d54082ddf513784eaa62662d2c8488278e713074bb"
        }
