          "parent_cp_end": 41,
          "parent_utf16_start": 0,
          "parent_utf16_end": 41,
          "full_parent_sha256_utf8": "4fe0a1b1aea536bf1b037751ad86b9ef8c2e57407a1b8a9938bcd0ba613d5e8c"
