          "paragraph_cp_start": 3461,
          "paragraph_cp_end": 3485,
          "paragraph_utf16_start": 3461,
          "paragraph_utf16_end": 3485,
          "actual_identity": "Bukhari6311/Muslim2710 AlBara; no Bukhari247 correction episode claim",
          "short_credit": "就寝の際の礼儀作法（サイード佐藤訳）",
          "source_cp_start": 175,
          "source_cp_end": 199,
          "source_utf16_start": 175,
          "source_utf16_end": 199,
