          "paragraph_utf16_end": 3581,
          "actual_identity": "Otsuka2023-09-01 prayer; Thawban Muslim591 Arabic context retained separately; source does not name narrator",
          "short_credit": "大塚マスジド 金曜日礼拝ホトバ要約",
