          "paragraph_cp_start": 4319,
          "paragraph_cp_end": 4364,
          "paragraph_utf16_start": 4319,
          "paragraph_utf16_end": 4364,
          "actual_identity": "Hisn120 p105–106, note referring97; Ahmad3712 Ibn Masud; grades attributed separately",
          "short_credit": "ムスリムの砦（サイード佐藤・ファーティマ佐藤訳）",
          "source_cp_start": 913,
          "source_cp_end": 958,
