          "paragraph_cp_start": 573,
          "paragraph_cp_end": 618,
          "paragraph_utf16_start": 573,
          "paragraph_utf16_end": 618,
          "reference": "2:186",
          "edition": "Tokyo Camii クルアーン 日本語読解 PDF edition01_03 2022-02-01",
          "parent_cp_start": 0,
          "parent_cp_end": 45,
